        overdub: { type: Bool; access: "get" | "set" | "observe" };
        /** 1 = the Punch-In button is enabled in the transport. */
        punch_in: { type: Bool; access: "get" | "set" | "observe" };
        /** 1 = the Punch-Out button is enabled in the transport. */
        punch_out: { type: Bool; access: "get" | "set" | "observe" };
        /** 1 = the Re-Enable Automation button is on. */
        re_enable_automation_enabled: { type: Bool; access: "get" | "observe" };
